DROP TABLE IF EXISTS "report_financial" CASCADE;
CREATE TABLE "report_financial" (
  "row_key" TEXT PRIMARY KEY,
  "code" TEXT,
  "date" TEXT,
  "driver" TEXT,
  "money" TEXT,
  "name" TEXT,
  "note" TEXT,
  "period" NUMERIC,
  "reg_head" TEXT,
  "reg_tail" TEXT,
  "short_name" TEXT,
  "status" TEXT,
  "type" TEXT,
  "vehicle_type" TEXT,
  "year" TEXT,
  "id" NUMERIC
);


DROP TABLE IF EXISTS "report_invoice" CASCADE;
CREATE TABLE "report_invoice" (
  "row_key" TEXT PRIMARY KEY,
  "bank" TEXT,
  "company" TEXT,
  "details" TEXT,
  "invoice_id" TEXT,
  "note" TEXT,
  "price" TEXT,
  "registration" TEXT,
  "selected_date_invoice" TEXT,
  "selected_date_transfer" TEXT,
  "status" TEXT,
  "total" NUMERIC,
  "truck_type" TEXT,
  "vat" NUMERIC,
  "id" TEXT,
  "path" TEXT,
  "group" TEXT
);

